@app.cell
def _(mo):
    mo.md(r"""
    ## Step 6: Identifiability: why the lab samples matter

    From temperature data alone, $UA$ and the pre-exponential factor $k_0$
    are hard to separate: their steady-state sensitivity vectors in the
    $[T\;\; T_j]$ measurement space point in nearly opposite, nearly
    collinear directions (cosine $-0.86$). A laboratory $C_A$ sample breaks
    the symmetry, because $C_A$ responds to the two parameters with a
    markedly different sensitivity ratio. The twin therefore sharpens its
    $UA$ estimate each time a lab result arrives.
    """)


@app.cell
def _(M, np):
    _UA0, _Fj_rep = (12.0, 0.2 / 60.0)
    _p = M.PLANT_P
    _roots = M.find_T_roots(_UA0, _Fj_rep, _p)
    _T_op = _roots[np.argmin(np.abs(_roots - 374.0))]

    def _branch(par, rel):
        if par == 'UA':
            ua2 = _UA0 * (1.0 + rel)
            r = M.find_T_roots(ua2, _Fj_rep, _p)
            T2 = r[np.argmin(np.abs(r - _T_op))]
            return (M.full_state(T2, ua2, _Fj_rep, _p) - M.full_state(_T_op, _UA0, _Fj_rep, _p)) / (_UA0 * rel)
        p2 = dict(_p, **{par: _p[par] * (1.0 + rel)})
        r = M.find_T_roots(_UA0, _Fj_rep, p2)
        T2 = r[np.argmin(np.abs(r - _T_op))]
        return (M.full_state(T2, _UA0, _Fj_rep, p2) - M.full_state(_T_op, _UA0, _Fj_rep, _p)) / (_p[par] * rel)
    _s_ua, _s_k0 = (_branch('UA', 0.0001), _branch('k0', 0.0001))
    _v_ua, _v_k0 = (_s_ua[1:] * _UA0, _s_k0[1:] * _p['k0'])
    _cosang = float(_v_ua @ _v_k0 / (np.linalg.norm(_v_ua) * np.linalg.norm(_v_k0)))
    print(f'd[T,Tj]/d(ln UA) = [{_v_ua[0]:+.2f}, {_v_ua[1]:+.2f}] K')
    print(f'd[T,Tj]/d(ln k0) = [{_v_k0[0]:+.2f}, {_v_k0[1]:+.2f}] K')
    print(f'cosine(UA, k0) in temperature space: {_cosang:+.3f}')
    print(f'dC_A/d(ln UA) = {_s_ua[0] * _UA0:+.3f} mol L-1, dC_A/d(ln k0) = {_s_k0[0] * _p['k0']:+.3f} mol L-1')
    print('-> opposite signs and different ratios: the lab sample separates them')


@app.cell
def _(mo):
    mo.md(r"""
    ## Step 7: Forecast: when cooling capacity runs out

    The twin fits its recent $UA$ estimates to an exponential decay, projects
    $UA(t)$ forward, and simulates its own model under the published controller.
    The forecast time is the first instant at which the required coolant flow
    reaches $F_{j,max}$: beyond it the setpoint can no longer be held. The
    page reports this as the latest recommended jacket-cleaning date.
    """)


@app.cell
def _(M, go, np):
    _DT = 10.0
    _plant = M.Plant(seed=11)
    _twin = M.TwinEKF(dt=_DT)
    _n = int(4 * 3600 / _DT)
    _hist_t, _hist_ua = ([], [])
    for _ in range(_n):
        _s = _plant.step(_DT)
        _pub = {k: v for k, v in _s.items() if not k.startswith('_')}
        _est = _twin.step(_pub)
        _hist_t.append(_s['t'])
        _hist_ua.append(_est['UA'])
    _hist_t, _hist_ua = (np.array(_hist_t), np.array(_hist_ua))
    _use = _hist_t > 3600.0
    _ln = np.log(np.maximum(_hist_ua[_use], 1e-06))
    _slope, _intercept = np.polyfit(_hist_t[_use], _ln, 1)
    _t_now = _hist_t[-1]
    _t_grid = np.linspace(_t_now, _t_now + 12 * 3600.0, 200)
    _ua_proj = np.exp(_intercept + _slope * _t_grid)
    _xa = _twin.x.copy()
    _I = _twin.I_ctrl
    _sat_time = None
    for _tg, _ua in zip(_t_grid, _ua_proj):
        _xa[3] = _ua
        _Fj, _e = M.controller(_xa[1], _I, M.CTRL)
        if _Fj >= M.CTRL['Fj_max'] - 1e-09 and _sat_time is None:
            _sat_time = _tg
        if not (_Fj <= M.CTRL['Fj_min'] and _e < 0 or (_Fj >= M.CTRL['Fj_max'] and _e > 0)):
            _I += _e * (_t_grid[1] - _t_grid[0])
        _sol = M._solve_ivp(lambda tt, xx: M._twin_rhs_s(xx, _Fj, M.PLANT_P['F'], M.PLANT_P['T0'], M.TWIN_P), (0, _t_grid[1] - _t_grid[0]), _xa, rtol=1e-06, atol=1e-08)
        _xa = _sol.y[:, -1]
    print(f'fitted fouling rate: {_slope * 3600:.4f} h-1 (true {-1 / (M.PLANT_P['tau_foul'] / 3600):.4f} h-1)')
    print(f'forecast: coolant saturates {(_sat_time - _t_now) / 3600:.1f} h after now (t = {_sat_time / 3600:.1f} h)')
    _fig0 = go.Figure(data=[dict(x=(_hist_t / 3600.0).tolist(), y=_hist_ua.tolist(), mode='lines', name='UA twin estimate'), dict(x=(_t_grid / 3600.0).tolist(), y=_ua_proj.tolist(), mode='lines', name='UA forecast', line=dict(dash='dash'))], layout=dict(title='Fouling trend and forecast', xaxis=dict(title='time [h]'), yaxis=dict(title='UA [J s-1 K-1]'), legend=dict(x=1.02, y=1.0, xanchor='left', yanchor='top'), margin=dict(r=150)))
    _fig0



@app.cell
def _(mo):
    mo.md(r"""
    ## Step 8: Fault detection: the filter hides the fault; the lab catches it

    A temperature-sensor bias of $+5$ K is injected halfway through a 6 h run.
    The filter absorbs the bias into biased $UA$ and $C_A$ estimates, so the
    fast temperature innovations stay deceptively quiet -- naive residual
    gating misses the fault. The delayed lab analyses are independent: when
    two consecutive lab samples disagree with the physics-based $C_A$
    prediction by more than three standard deviations each, the twin flags a
    sensor fault instead of mis-attributing the bias to faster fouling.
    """)


@app.cell
def _(M, go, np):
    _DT = 10.0
    _plant = M.Plant(seed=21)
    _twin = M.TwinEKF(dt=_DT)
    _n = int(6 * 3600 / _DT)
    for _i in range(_n):
        if _i == _n // 3:
            _plant.sensor_bias_T = 5.0
        _s = _plant.step(_DT)
        _pub = {k: v for k, v in _s.items() if not k.startswith('_')}
        _twin.step(_pub)
    _li = [(t, iv, sd) for t, iv, sd in _twin.lab_innov if t / 3600.0 >= 0.6]
    _det_t = None
    for _j in range(1, len(_li)):
        if abs(_li[_j][1]) > 3 * _li[_j][2] and abs(_li[_j - 1][1]) > 3 * _li[_j - 1][2]:
            _det_t = _li[_j][0] / 3600.0
            break
    print(f'fault injected at t = 2.0 h; flagged at t = {_det_t:.2f} h' if _det_t else 'fault NOT detected')
    print(f'fast-innovation mean after fault: {np.array(_twin.resid_T[_n // 3:]).mean():+.3f} K  (filter absorbed it)')
    _lt = [t / 3600.0 for t, iv, sd in _li]
    _liv = [iv for t, iv, sd in _li]
    _band = [3 * sd for t, iv, sd in _li]
    _fig0 = go.Figure(data=[dict(x=_lt, y=_liv, mode='markers', name='lab innovation', marker=dict(size=8)), dict(x=_lt, y=_band, mode='lines', name='+3 sigma', line=dict(dash='dash', color='red')), dict(x=_lt, y=[-b for b in _band], mode='lines', name='-3 sigma', line=dict(dash='dash', color='red'))], layout=dict(title='Lab C_A innovations under a +5 K sensor bias', xaxis=dict(title='time [h]'), yaxis=dict(title='innovation [mol L-1]'), legend=dict(x=1.02, y=1.0, xanchor='left', yanchor='top'), margin=dict(r=150)))
    _fig0



@app.cell
def _(mo):
    mo.md(r"""
    ## Step 9: What the twin may and may not see

    The honesty architecture is enforced in code, not by convention. The plant
    object owns the hidden parameters and the true state; its `step` method
    returns a published sample plus a `_true` channel used only for scoring.
    The driver strips every key starting with `_` before the twin's `step`
    sees the sample, and a static test asserts that the twin's source contains
    no reference to the plant's parameter dictionary, its fouling function, or
    the truth channel. Scenes 1--5 are therefore a digital shadow in the sense
    of Kritzinger et al. (2018): data flows from the plant to the twin only.
    Scene 6 closes the loop -- the twin writes an adjusted setpoint back --
    which is what makes it a twin in that taxonomy.
    """)


@app.cell
def _(MODEL_SRC):
    _src = MODEL_SRC
    _twin_src = _src[_src.index('class TwinEKF'):]
    _forbidden = ['PLANT_P', 'ua_of_t', '_true', 'plant_rhs', 'sensor_bias_T']
    print('forbidden tokens in twin source:', [tok for tok in _forbidden if tok in _twin_src] or 'none')
    _sample_keys = ['t', 'T', 'T_j', 'F', 'T0', 'Fj']
    print('twin receives per sample:', _sample_keys)
    print('twin never receives: C_A (except delayed lab), UA, k0, E_a')


@app.cell
def _(mo):
    mo.md(r"""
    ## Step 10: The twin: particle filter

    The particle-filter twin estimates the same augmented state vector
    $x = [C_A\;\; T\;\; T_j\;\; UA]^{\mathsf{T}}$ as the EKF twin, where
    $C_A$ is the reactant concentration (mol L$^{-1}$), $T$ the reactor
    temperature (K), $T_j$ the jacket temperature (K), and $UA$ the fouling
    conductance (J s$^{-1}$ K$^{-1}$). It represents the posterior by a
    weighted ensemble of $N$ particles ($N = 200$ by default): each step
    propagates every particle through the nominal twin model with process
    noise, reweights the ensemble by the $T$/$T_j$ measurement likelihood,
    and resamples systematically when the effective sample size $N_{\mathrm{eff}}$
    falls below the threshold $N_{\mathrm{thr}} = N/2$. The drifting
    conductance is tracked with Liu--West kernel smoothing (discount factor
    $\gamma = 0.97$). The point estimate is the weighted particle mean, and
    uncertainty is reported as weighted particle quantiles. The `step`
    interface is identical to the EKF twin's, so the driver feeds both
    twins the same published samples.
    """)


@app.cell
def _(M, PF):
    _twin = PF.TwinPF(dt=10.0, N=200, seed=0)
    print('twin state: [C_A, T, T_j, UA] as a weighted particle ensemble')
    print(f'N = {_twin.N}, gamma = {_twin.gamma}, resample_thr = {_twin.resample_thr * _twin.N:.0f}')
    print(f'per-step sigma_p: C_A = {_twin.sigma_p_CA:.2e} mol L-1, T = {_twin.sigma_p_T:.2e} K, T_j = {_twin.sigma_p_Tj:.2e} K')
    _plant = M.Plant(seed=7)
    _s = _plant.step(10.0)
    _est = _twin.step({k: v for k, v in _s.items() if not k.startswith('_')})
    print('step() returns:', sorted(_est.keys()))
    print(f'weighted-mean UA after one step: {_est['UA']:.3f} J s-1 K-1')
    print(f'N_eff after one step: {_twin.n_eff_hist[-1]:.1f} of {_twin.N}')
    print('diagnostics():', sorted(_twin.diagnostics().keys()))


@app.cell
def _(mo):
    mo.md(r"""
    ## Step 11: Scene B1: fouling tracking, PF against EKF

    One plant drives both twins with the identical seed and the identical
    published samples, so differences in the outputs are attributable to the
    estimators. The comparison-scene convention of the estimator panel
    contract is honored exactly: the seed is shared, the samples are shared,
    and only the estimators differ. The numbers below come from a 2 h
    nominal-fouling run with $N = 100$ particles; the App tab reproduces the
    comparison live at $N = 200$.
    """)


@app.cell
def _(M, PF, go, np):
    _DT = 10.0
    _plant = M.Plant(seed=7)
    _ekf = M.TwinEKF(dt=_DT)
    _pf = PF.TwinPF(dt=_DT, N=100, seed=7)
    _n = int(2 * 3600 / _DT)
    _t, _ua_t, _ua_e, _ua_p, _ca_t, _ca_e, _ca_p = ([] for _ in range(7))
    for _ in range(_n):
        _s = _plant.step(_DT)
        _pub = {k: v for k, v in _s.items() if not k.startswith('_')}
        _ee, _ep = (_ekf.step(_pub), _pf.step(_pub))
        _tr = _s['_true']
        _t.append(_s['t'] / 3600.0)
        _ua_t.append(_tr['UA'])
        _ua_e.append(_ee['UA'])
        _ua_p.append(_ep['UA'])
        _ca_t.append(_tr['C_A'])
        _ca_e.append(_ee['C_A'])
        _ca_p.append(_ep['C_A'])
    _b = int(1800 / _DT)

    def _rmse(a, c):
        return float(np.sqrt(np.mean((np.array(a[_b:]) - np.array(c[_b:])) ** 2)))
    print(f'EKF UA  RMSE: {_rmse(_ua_e, _ua_t):.3f} J s-1 K-1')
    print(f'PF  UA  RMSE: {_rmse(_ua_p, _ua_t):.3f} J s-1 K-1')
    print(f'EKF C_A RMSE: {_rmse(_ca_e, _ca_t):.4f} mol L-1')
    print(f'PF  C_A RMSE: {_rmse(_ca_p, _ca_t):.4f} mol L-1')
    print(f'PF N_eff: min {min(_pf.n_eff_step):.1f}, median {float(np.median(_pf.n_eff_step)):.1f} of {_pf.N}')
    _fig0 = go.Figure(data=[dict(x=_t, y=_ua_t, mode='lines', name='UA true (hidden)'), dict(x=_t, y=_ua_e, mode='lines', name='UA EKF estimate'), dict(x=_t, y=_ua_p, mode='lines', name='UA PF weighted mean')], layout=dict(title='Fouling tracking: PF against EKF', xaxis=dict(title='time [h]'), yaxis=dict(title='UA [J s-1 K-1]'), legend=dict(x=1.02, y=1.0, xanchor='left', yanchor='top'), margin=dict(r=160)))
    _fig0



@app.cell
def _(mo):
    mo.md(r"""
    ## Step 12: Scene B2: sensor-bias fault and the particle cloud

    A temperature-sensor bias of $+5$ K is injected at $t = 1.1$ h of a 3 h
    run. A biased temperature reading admits two explanations -- sensor bias
    or accelerated fouling -- and the particle cloud sustains both
    hypotheses: the three histograms below show the $UA$ particle density
    (40 bins) at the last lab delivery before the fault, the first delivery
    after it (whose sample still predates the fault), and the second
    delivery after it (whose sample postdates the fault and discriminates
    between the hypotheses). The delayed lab innovations are the independent
    check: they stay small until a post-fault lab sample arrives.
    """)


@app.cell
def _(M, PF, go, np):
    _DT = 10.0
    _plant = M.Plant(seed=21)
    _pf = PF.TwinPF(dt=_DT, N=100, seed=21)
    _n = int(3 * 3600 / _DT)
    _onset_h = 1.1
    _onset_i = int(_onset_h * 3600 / _DT)
    _snaps = []
    for _i in range(_n):
        if _i == _onset_i:
            _plant.sensor_bias_T = 5.0
        _s = _plant.step(_DT)
        _pub = {k: v for k, v in _s.items() if not k.startswith('_')}
        _pf.step(_pub)
        if 'lab_C_A' in _pub:
            _snaps.append((_s['t'] / 3600.0, _pf.X[:, 3].copy(), _pf.w.copy()))
    _pre = [_sn for _sn in _snaps if _sn[0] < _onset_h][-1]
    _post0, _post1 = [_sn for _sn in _snaps if _sn[0] >= _onset_h][:2]
    print(f'fault injected at t = {_onset_h:.1f} h (+5 K bias on the T sensor)')
    for _lbl, _sn in (('pre-fault', _pre), ('post-fault, pre-lab', _post0), ('post-lab', _post1)):
        _mu = float(np.sum(_sn[2] * _sn[1]))
        print(f'{_lbl:>20s} (t = {_sn[0]:.2f} h): UA cloud mean {_mu:.2f} J s-1 K-1')
    print('lab innovations after the fault:')
    _shown = 0
    for _td, _iv, _sd in _pf.lab_innov:
        if _td / 3600.0 >= _onset_h and _shown < 4:
            print(f'  t = {_td / 3600.0:.2f} h: {_iv:+.3f} mol L-1 ({_iv / _sd:+.1f} sigma)')
            _shown += 1
    _traces = []
    for _lbl, _sn in (('pre-fault', _pre), ('post-fault, pre-lab', _post0), ('post-lab', _post1)):
        _counts, _edges = np.histogram(_sn[1], bins=40, weights=_sn[2], density=True)
        _ctr = ((_edges[:-1] + _edges[1:]) / 2.0).tolist()
        _traces.append(dict(x=_ctr, y=_counts.tolist(), type='bar', name=_lbl, opacity=0.6))
    _fig0 = go.Figure(data=_traces, layout=dict(title='UA particle cloud around a +5 K sensor bias', xaxis=dict(title='UA [J s-1 K-1]'), yaxis=dict(title='density [-]'), legend=dict(x=1.02, y=1.0, xanchor='left', yanchor='top'), margin=dict(r=170), barmode='overlay'))
